Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Ltac kabsA DT :=
  lazymatch goal with |- kentry_ok _ ?E ?m (KWord (SA (ELit 0) ?x) ?w (ELit ?v)) =>
    let x' := eval vm_compute in x in
    let w' := eval vm_compute in w in
    let r := eval vm_compute in (dlookupn D_DIAG_A x' w') in
    lazymatch r with
    | Some ?zs =>
      change (kentry_ok asegs E m (KWord (SA (ELit 0) x') w' (ELit v)));
      apply (kword_of_dstat_rs D_DIAG_A E m x' w' v zs DT); [lia | cbn; lia | lia | vm_compute; reflexivity | vm_compute; reflexivity]
    | _ => fail "kabsA: address not in D_DIAG_A" x'
    end
  end.

Definition A_NUMPUT_UL : Z := 0x132a34.
Definition A_NUMPUT_L : Z := 0x1324dc.
Definition A_CTYPE_OBJ : Z := 0x6c45b8.
Definition DP_WIN : Z := 8192.

Ltac regsub_inA H :=
  repeat match goal with
  | G : getr ?R ?r = ?v |- _ =>
      match type of H with
      | context [getr R ?r'] => replace (getr R r') with v in H by (symmetry; exact G)
      end
  end.
Ltac wnorm_inA H :=
  unfold adenot in H; cbn [a_base a_off edenot] in H; evs_in H; regsub_inA H;
  revert H; znorm; intros H;
  rewrite ?Z.add_0_r in H; repeat rewrite Z.mod_small in H by lia.

